theory.code:
SINGLETON (domyslny):
A a1 = context.getBean(A.class);
A a2 = context.getBean(A.class);
a1 == a2  -> TRUE (ta sama instancja)

PROTOTYPE:
B b1 = context.getBean(B.class);
B b2 = context.getBean(B.class);
b1 == b2  -> FALSE (dwie rozne instancje)

@Component // domyslny zakres = singleton, nie trzeba nic dodawac
class SingletonCounter {
    private int value = 0;
    int incrementAndGet() { return ++value; }
}

SingletonCounter first = context.getBean(SingletonCounter.class);
SingletonCounter second = context.getBean(SingletonCounter.class);
first.incrementAndGet();

System.out.println(first == second);           // true - TA SAMA instancja
System.out.println(second.incrementAndGet());  // 2 - widzi zmiane zrobiona przez "first"

@Bean
@Scope("prototype")
PrototypeCounter prototypeCounter() {
    return new PrototypeCounter(); // nowy obiekt za kazdym wywolaniem metody
}

PrototypeCounter first = context.getBean(PrototypeCounter.class);
PrototypeCounter second = context.getBean(PrototypeCounter.class);
PrototypeCounter third = context.getBean(PrototypeCounter.class);

System.out.println(first == second);  // false - ZAWSZE dla prototype
System.out.println(first.getInstanceId() != second.getInstanceId()); // true

@Service // domyslnie singleton
class BrokenSingletonHoldingPrototype {
    private final PrototypeCounter counter;

    BrokenSingletonHoldingPrototype(PrototypeCounter counter) {
        this.counter = counter; // wstrzykniete RAZ, przy tworzeniu singletona
    }

    int useCounter() {
        return counter.getInstanceId(); // ZAWSZE to samo ID!
    }
}
// useCounter() wywolane 3x -> 3x TO SAMO ID, mimo ze counter to "prototype"

@Service
class FixedServiceUsingObjectProvider {
    private final ObjectProvider<PrototypeCounter> provider;

    FixedServiceUsingObjectProvider(ObjectProvider<PrototypeCounter> provider) {
        this.provider = provider; // wstrzykniety provider, NIE gotowy obiekt
    }

    int useFreshCounter() {
        return provider.getObject().getInstanceId(); // SWIEZA instancja za kazdym razem
    }
}
// useFreshCounter() wywolane 3x -> 3x ROZNE ID
